jest.mock(
  "rollup-plugin-dev",
  () => jest.fn((config: any) => ({ name: "dev", ...config })),
  { virtual: true },
);

jest.mock(
  "rollup-plugin-livereload",
  () => jest.fn((config: any) => ({ name: "livereload", ...config })),
  { virtual: true },
);

import { devServerPlugins } from "../../src/servicenow/dev-server-plugins";

const makeCredential = (url = "https://dev12345.service-now.com/") => ({
  getUrl: () => new URL(url),
  getHeaders: async () => ({ Authorization: "Bearer token123" }),
});

describe("devServerPlugins", () => {
  let consoleWarnSpy: jest.SpyInstance;

  beforeEach(() => {
    jest.clearAllMocks();
    consoleWarnSpy = jest.spyOn(console, "warn").mockImplementation(() => {});
  });

  afterEach(() => {
    consoleWarnSpy.mockRestore();
  });

  describe("plugin structure", () => {
    test("should return undefined when watchPaths is empty", async () => {
      const result = await devServerPlugins({
        credential: undefined,
        proxyPaths: [],
        watchPaths: [],
      });
      expect(result).toBeUndefined();
    });

    test("should warn when watchPaths is empty", async () => {
      await devServerPlugins({
        credential: undefined,
        proxyPaths: [],
        watchPaths: [],
      });
      expect(consoleWarnSpy).toHaveBeenCalledWith(
        "No watch paths provided for dev server. Please provide at least one path to watch for changes.",
      );
    });

    test("should return an array of two plugins when watchPaths is provided", async () => {
      const result = await devServerPlugins({
        credential: makeCredential(),
        proxyPaths: [],
        watchPaths: ["dist/static"],
      });
      expect(Array.isArray(result)).toBe(true);
      expect(result).toHaveLength(2);
    });

    test("should return devServer as first plugin and livereload as second", async () => {
      const result = await devServerPlugins({
        credential: makeCredential(),
        proxyPaths: [],
        watchPaths: ["dist/static"],
      });
      expect(result![0].name).toBe("dev");
      expect(result![1].name).toBe("livereload");
    });
  });

  describe("watchPaths handling", () => {
    test("should pass watchPaths as dirs to the dev server", async () => {
      const devServerMock = require("rollup-plugin-dev");
      await devServerPlugins({
        credential: makeCredential(),
        proxyPaths: [],
        watchPaths: ["dist/esm"],
      });
      expect(devServerMock).toHaveBeenCalledWith(
        expect.objectContaining({ dirs: ["dist/esm"] }),
      );
    });

    test("should pass multiple watchPaths as dirs", async () => {
      const devServerMock = require("rollup-plugin-dev");
      await devServerPlugins({
        credential: makeCredential(),
        proxyPaths: [],
        watchPaths: ["dist/esm", "dist/cjs"],
      });
      expect(devServerMock).toHaveBeenCalledWith(
        expect.objectContaining({ dirs: ["dist/esm", "dist/cjs"] }),
      );
    });

    test("should start the dev server on port 3000", async () => {
      const devServerMock = require("rollup-plugin-dev");
      await devServerPlugins({
        credential: makeCredential(),
        proxyPaths: [],
        watchPaths: ["dist/static"],
      });
      expect(devServerMock).toHaveBeenCalledWith(
        expect.objectContaining({ port: 3000 }),
      );
    });

    test("should configure livereload to watch the watchPaths", async () => {
      const livereloadMock = require("rollup-plugin-livereload");
      await devServerPlugins({
        credential: makeCredential(),
        proxyPaths: [],
        watchPaths: ["dist/esm"],
      });
      expect(livereloadMock).toHaveBeenCalledWith(
        expect.objectContaining({ watch: ["dist/esm"] }),
      );
    });
  });

  describe("credential handling", () => {
    test("should warn when credential is undefined and proxyPaths is non-empty", async () => {
      await devServerPlugins({
        credential: undefined,
        proxyPaths: ["/api"],
        watchPaths: ["dist/static"],
      });
      expect(consoleWarnSpy).toHaveBeenCalledWith(
        "credential not provided. Dev server will start without proxying to ServiceNow instance.",
      );
    });

    test("should not warn when credential is undefined and proxyPaths is also empty", async () => {
      await devServerPlugins({
        credential: undefined,
        proxyPaths: [],
        watchPaths: ["dist/static"],
      });
      expect(consoleWarnSpy).not.toHaveBeenCalled();
    });

    test("should warn when credential is missing getUrl", async () => {
      await devServerPlugins({
        credential: { getHeaders: async () => ({}) } as any,
        proxyPaths: [],
        watchPaths: ["dist/static"],
      });
      expect(consoleWarnSpy).toHaveBeenCalled();
    });

    test("should warn when credential is missing getHeaders", async () => {
      await devServerPlugins({
        credential: {
          getUrl: () => new URL("https://dev.service-now.com"),
        } as any,
        proxyPaths: [],
        watchPaths: ["dist/static"],
      });
      expect(consoleWarnSpy).toHaveBeenCalled();
    });

    test("should not warn when a valid credential is provided", async () => {
      await devServerPlugins({
        credential: makeCredential(),
        proxyPaths: [],
        watchPaths: ["dist/static"],
      });
      expect(consoleWarnSpy).not.toHaveBeenCalled();
    });
  });

  describe("proxy configuration", () => {
    test("should create a proxy entry for each proxyPath", async () => {
      const devServerMock = require("rollup-plugin-dev");
      await devServerPlugins({
        credential: makeCredential(),
        proxyPaths: ["/api/now", "/x_app"],
        watchPaths: ["dist/static"],
      });
      const [{ proxy }] = devServerMock.mock.calls[0];
      expect(proxy).toHaveLength(2);
      expect(proxy[0].from).toBe("/api/now");
      expect(proxy[1].from).toBe("/x_app");
    });

    test("should build proxy target from credential URL with trailing slash stripped", async () => {
      const devServerMock = require("rollup-plugin-dev");
      await devServerPlugins({
        credential: makeCredential("https://dev12345.service-now.com/"),
        proxyPaths: ["/api"],
        watchPaths: ["dist/static"],
      });
      const [{ proxy }] = devServerMock.mock.calls[0];
      expect(proxy[0].to).toBe("https://dev12345.service-now.com/api");
    });

    test("should add websocket:true for the /amb path", async () => {
      const devServerMock = require("rollup-plugin-dev");
      await devServerPlugins({
        credential: makeCredential(),
        proxyPaths: ["/amb", "/api"],
        watchPaths: ["dist/static"],
      });
      const [{ proxy }] = devServerMock.mock.calls[0];
      const ambEntry = proxy.find((p: any) => p.from === "/amb");
      const apiEntry = proxy.find((p: any) => p.from === "/api");
      expect(ambEntry.opts.websocket).toBe(true);
      expect(apiEntry.opts.websocket).toBeUndefined();
    });

    test("should call getHeaders exactly once regardless of number of proxy paths", async () => {
      const getHeaders = jest
        .fn()
        .mockResolvedValue({ Authorization: "Bearer token123" });
      await devServerPlugins({
        credential: {
          getUrl: () => new URL("https://dev.service-now.com"),
          getHeaders,
        },
        proxyPaths: ["/api", "/amb", "/scripts/"],
        watchPaths: ["dist/static"],
      });
      expect(getHeaders).toHaveBeenCalledTimes(1);
    });

    test("should build proxy target correctly when credential URL has no trailing slash", async () => {
      const devServerMock = require("rollup-plugin-dev");
      await devServerPlugins({
        credential: makeCredential("https://dev12345.service-now.com"),
        proxyPaths: ["/api"],
        watchPaths: ["dist/static"],
      });
      const [{ proxy }] = devServerMock.mock.calls[0];
      expect(proxy[0].to).toBe("https://dev12345.service-now.com/api");
    });

    test("should pass an empty proxy array when credential is provided but proxyPaths is empty", async () => {
      const devServerMock = require("rollup-plugin-dev");
      await devServerPlugins({
        credential: makeCredential(),
        proxyPaths: [],
        watchPaths: ["dist/static"],
      });
      const [{ proxy }] = devServerMock.mock.calls[0];
      expect(proxy).toHaveLength(0);
    });

    test("should auth headers override conflicting keys in incoming request headers", async () => {
      const devServerMock = require("rollup-plugin-dev");
      await devServerPlugins({
        credential: {
          getUrl: () => new URL("https://dev.service-now.com"),
          getHeaders: async () => ({ Authorization: "Bearer fresh-token" }),
        },
        proxyPaths: ["/api"],
        watchPaths: ["dist/static"],
      });
      const [{ proxy }] = devServerMock.mock.calls[0];
      const rewrite = proxy[0].opts.replyOptions.rewriteRequestHeaders;
      const result = rewrite({} as Request, {
        Authorization: "Bearer stale-token",
      });
      expect(result.Authorization).toBe("Bearer fresh-token");
    });

    test("should merge auth headers into existing request headers", async () => {
      const devServerMock = require("rollup-plugin-dev");
      await devServerPlugins({
        credential: {
          getUrl: () => new URL("https://dev.service-now.com"),
          getHeaders: async () => ({
            Authorization: "Bearer token123",
            "X-Custom": "header",
          }),
        },
        proxyPaths: ["/api"],
        watchPaths: ["dist/static"],
      });
      const [{ proxy }] = devServerMock.mock.calls[0];
      const rewrite = proxy[0].opts.replyOptions.rewriteRequestHeaders;
      const result = rewrite({} as Request, {
        "Content-Type": "application/json",
      });
      expect(result).toEqual({
        "Content-Type": "application/json",
        Authorization: "Bearer token123",
        "X-Custom": "header",
      });
    });

    test("should pass an empty proxy array when no credential is provided", async () => {
      const devServerMock = require("rollup-plugin-dev");
      await devServerPlugins({
        credential: undefined,
        proxyPaths: ["/api"],
        watchPaths: ["dist/static"],
      });
      const [{ proxy }] = devServerMock.mock.calls[0];
      expect(proxy).toHaveLength(0);
    });
  });

  describe("missing optional dependencies", () => {
    afterEach(() => {
      jest.resetModules();
    });

    test("should throw when rollup-plugin-dev is not installed", async () => {
      jest.resetModules();
      jest.doMock(
        "rollup-plugin-dev",
        () => {
          throw Object.assign(
            new Error("Cannot find module 'rollup-plugin-dev'"),
            { code: "MODULE_NOT_FOUND" },
          );
        },
        { virtual: true },
      );
      jest.doMock("rollup-plugin-livereload", () => jest.fn(), {
        virtual: true,
      });
      const {
        devServerPlugins: freshFn,
      } = require("../../src/servicenow/dev-server-plugins");
      await expect(
        freshFn({
          credential: undefined,
          proxyPaths: [],
          watchPaths: ["dist/static"],
        }),
      ).rejects.toThrow(
        "rollup-plugin-dev is not installed or failed to load. Please install it to enable the dev server.",
      );
    });

    test("should throw when rollup-plugin-livereload is not installed", async () => {
      jest.resetModules();
      jest.doMock("rollup-plugin-dev", () => jest.fn(), { virtual: true });
      jest.doMock(
        "rollup-plugin-livereload",
        () => {
          throw Object.assign(
            new Error("Cannot find module 'rollup-plugin-livereload'"),
            { code: "MODULE_NOT_FOUND" },
          );
        },
        { virtual: true },
      );
      const {
        devServerPlugins: freshFn,
      } = require("../../src/servicenow/dev-server-plugins");
      await expect(
        freshFn({
          credential: undefined,
          proxyPaths: [],
          watchPaths: ["dist/static"],
        }),
      ).rejects.toThrow(
        "rollup-plugin-livereload is not installed or failed to load. Please install it to enable the dev server.",
      );
    });
  });
});
